insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 14, 'Chapter 2, Verse 14', 'मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-14', 'en', 'Contact of the senses with their objects brings cold and heat, pleasure and pain. These come and go; they do not last. Bear them patiently, O Arjuna.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-14', 'en', 'Every feeling, good or bad, is a visitor, not a resident. If you remember that it will pass, you stop being thrown around by it.', 'Krishna begins with something everyone knows from daily life: the senses meet the world and we feel heat or cold, comfort or pain. His point is that these experiences are always moving. They arrive, stay a while and leave. The Sanskrit word titikṣā means patient endurance, a calm strength that lets you feel fully without being overturned. This is not about suppressing feelings. It is about knowing that you are bigger than any single feeling, so you can wait for it to pass and then act wisely.', '[{"word":"mātrā-sparśa","meaning":"contact of the senses with objects"},{"word":"anitya","meaning":"not lasting, temporary"},{"word":"titikṣā","meaning":"patient endurance"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-14-story', 'Thirteen years in the forest', 'After losing everything in a game of dice, the Pandavas lived twelve years in the forest and a thirteenth in disguise. Heat, hunger and humiliation came and went. They endured, and when the years ended they were still themselves.', 'Five brothers and Draupadi walking through a monsoon forest, calm faces under heavy rain.');
insert into verse_stories (verse_id, story_id) values ('gita-2-14', 'gita-2-14-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-14', 'en', 'Name the weather', 'When a strong feeling arrives today, say to yourself: this is weather, and weather passes. Wait ten breaths before reacting.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-14', 'According to this verse, pleasure and pain are...', array['Permanent', 'Temporary, they come and go', 'Only imagined', 'A punishment']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-14', 'What does Krishna ask Arjuna to do with them?', array['Avoid them', 'Fight them', 'Bear them patiently', 'Ignore all feelings forever']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 20, 'Chapter 2, Verse 20', 'न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-20', 'en', 'The Self is never born and never dies. It did not come into being and will not cease to be. Unborn, eternal, everlasting and ancient, it is not killed when the body is killed.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-20', 'en', 'What you truly are is deeper than your body and your life story. That core cannot be harmed, which is a source of courage.', 'This is one of the most quoted verses of the Gita. Arjuna fears killing his elders, so Krishna lifts the conversation to a deeper level. The Self, called ātman, is not the body. It was not born when the body was born and does not end when the body ends. The verse piles up words for this: unborn, eternal, everlasting, ancient. For a reader today, it offers a steady place inside that loss and failure cannot touch, which gives the courage to face hard things.', '[{"word":"ātman","meaning":"the Self, your deepest being"},{"word":"aja","meaning":"unborn"},{"word":"nitya","meaning":"eternal"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-20-story', 'Nachiketa asks Death', 'In the Katha Upanishad, the boy Nachiketa is sent to Yama, the lord of death. Offered wealth and long life instead, he refuses and asks only one thing: what remains when a person dies? Yama, impressed, teaches him that the Self is never born and never dies.', 'A young boy sitting fearlessly before a calm, regal Yama at the gate of a quiet palace.');
insert into verse_stories (verse_id, story_id) values ('gita-2-20', 'gita-2-20-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-20', 'en', 'Find the still centre', 'Sit for two minutes and notice that thoughts and sensations change, but the one who notices them stays the same. Rest there.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-20', 'What does this verse say about the Self?', array['It dies with the body', 'It is never born and never dies', 'It is born every morning', 'It belongs to the gods']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-20', 'When the body is killed, the Self is...', array['Destroyed', 'Weakened', 'Not killed', 'Punished']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 22, 'Chapter 2, Verse 22', 'वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-22', 'en', 'Just as a person throws away worn-out clothes and puts on new ones, so the embodied Self casts off worn-out bodies and enters new ones.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-22', 'en', 'Change, even the biggest change, is like changing clothes. The wearer stays. This softens our fear of endings.', 'Krishna gives Arjuna a simple picture he can hold on to. We do not mourn an old shirt when we put on a new one. In the same way, the dehī, the one who lives in the body, moves from body to body. Indian tradition reads this as rebirth, but the verse also speaks to everyday change: jobs, homes and stages of life are outer clothing. Who you are underneath continues, and that makes letting go less frightening.', '[{"word":"vāsāṁsi","meaning":"clothes, garments"},{"word":"jīrṇa","meaning":"worn out, old"},{"word":"dehī","meaning":"the one who dwells in the body"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-22-story', 'Arjuna lays down his bow', 'On the field of Kurukshetra, Arjuna sees his teachers, grandfather and cousins on the other side. Overcome with grief, he drops his bow and refuses to fight. Krishna begins his teaching by reminding him that bodies change, but the Self does not.', 'Arjuna seated in his chariot with his bow on the floor, Krishna turning toward him with a gentle smile.');
insert into verse_stories (verse_id, story_id) values ('gita-2-22', 'gita-2-22-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-22', 'en', 'Let one old thing go', 'Pick one old habit, belief or grudge that no longer fits you. Write it down, and decide to set it aside like a worn-out shirt.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-22', 'What image does Krishna use in this verse?', array['A river', 'Changing old clothes for new', 'A burning lamp', 'A chariot wheel']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-22', 'Who ''changes clothes'' in this teaching?', array['The embodied Self', 'The king', 'The gods', 'The body']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-47', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 47, 'Chapter 2, Verse 47', 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-47', 'en', 'You have a right to your actions alone, never to their results. Do not let the fruit of action be your motive, and do not be attached to doing nothing.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-47', 'en', 'Put your whole heart into the work and let go of the outcome. Results depend on many things; your effort depends on you.', 'Perhaps the most famous line of the Gita. It has four parts: you have a right to act; you have no claim over the results; do not let results be your only motive; and do not use this as an excuse to do nothing. Krishna is not saying results do not matter. He is saying they are shaped by many forces beyond you, so tying your peace to them makes you anxious. Do your best, offer it, and let the outcome come. This is the seed of karma yoga, the path of selfless action.', '[{"word":"karma","meaning":"action, work"},{"word":"adhikāra","meaning":"right, rightful claim"},{"word":"phala","meaning":"fruit, result"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-47-story', 'The heart of Krishna''s advice', 'Arjuna is frozen, afraid of what victory or defeat will cost. Krishna tells him that worrying about results is what paralyses him. His duty is to act well; the outcome is not his to own.', 'Krishna pointing forward from the chariot at sunrise, Arjuna lifting his bow again.');
insert into verse_stories (verse_id, story_id) values ('gita-2-47', 'gita-2-47-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-47', 'en', 'Effort, not outcome', 'Choose one task today and do it as well as you can without checking how it will be judged. Notice how much lighter it feels.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-47', 'According to this verse, you have a right to...', array['The results of your work', 'Your actions only', 'Other people''s actions', 'Rest only']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-47', 'Should you stop acting because results are uncertain?', array['Yes, avoid action', 'No, do not be attached to inaction', 'Only on holy days', 'Only if others agree']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-48', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 48, 'Chapter 2, Verse 48', 'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-48', 'en', 'Established in yoga, perform your actions, giving up attachment, O Arjuna. Stay the same in success and failure. This evenness of mind is called yoga.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-48', 'en', 'Yoga is not only a posture. It is a balanced mind that does not swing wildly between winning and losing.', 'Here the Gita gives one of its clearest definitions: yoga is samatvam, evenness. Krishna calls Arjuna Dhanañjaya, winner of wealth, a reminder of his past successes, and then asks him to hold success and failure with the same steady mind. This is not indifference. You still care and still try hard, but your balance does not depend on how things turn out. Many teachers see this verse as the bridge between action and meditation.', '[{"word":"yoga-stha","meaning":"established in yoga"},{"word":"samatva","meaning":"evenness, equanimity"},{"word":"siddhi / asiddhi","meaning":"success / failure"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-48-story', 'Yudhishthira''s even mind', 'Yudhishthira, the eldest Pandava, was known for staying steady whether he was crowned king or sent into exile. Even after great losses, he answered questions of dharma calmly, which is why he was called Dharmaraja.', 'A calm king in simple forest clothes, seated beneath a banyan tree, half his face lit by sunset.');
insert into verse_stories (verse_id, story_id) values ('gita-2-48', 'gita-2-48-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-48', 'en', 'Same face for praise and blame', 'The next time you get praise or criticism today, pause and respond with the same calm tone either way.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-48', 'What does this verse call ''yoga''?', array['Physical strength', 'Evenness of mind', 'Fasting', 'Winning battles']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-48', 'How should one be in success and failure?', array['Proud in success', 'The same in both', 'Sad in both', 'Angry in failure']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-56', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 56, 'Chapter 2, Verse 56', 'दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-56', 'en', 'One whose mind is not shaken by sorrow, who does not crave pleasure, and who is free from attachment, fear and anger, is called a sage of steady wisdom.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-56', 'en', 'Wisdom shows in how we handle hard times and good times. A steady mind is free of craving, fear and anger.', 'Arjuna asks what a truly wise person looks like, and Krishna paints the sthita-dhī, the one of steady mind. In sorrow they are not shaken; in pleasure they do not grasp for more. Three forces that usually drive us, attachment (rāga), fear (bhaya) and anger (krodha), have lost their hold. The word muni means a sage, often one who is quiet. The verse gives us a practical mirror: when these three rise in us, we know where our work lies.', '[{"word":"sthita-dhī","meaning":"one of steady mind"},{"word":"rāga","meaning":"attachment, clinging"},{"word":"muni","meaning":"sage, quiet one"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-56-story', 'Rama hears of his exile', 'In the Ramayana, on the morning Rama was to be crowned, he was told he must instead leave for the forest for fourteen years. The poet Valmiki says his face did not change. He accepted it with the same calm he would have shown on his coronation.', 'Prince Rama bowing to his father in a palace hall, serene, while courtiers look on in shock.');
insert into verse_stories (verse_id, story_id) values ('gita-2-56', 'gita-2-56-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-56', 'en', 'Spot the three thieves', 'Notice today when craving, fear or anger tries to take over a decision. Just naming which one it is weakens its grip.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-56', 'A person of steady wisdom is free from...', array['Work and family', 'Attachment, fear and anger', 'All thinking', 'Food and sleep']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-56', 'In the story, how did Rama react to his exile?', array['He refused to go', 'He became angry', 'He accepted it calmly', 'He hid in the palace']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-62', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 62, 'Chapter 2, Verse 62', 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-62', 'en', 'When a person dwells on sense objects, attachment to them arises. From attachment comes desire, and from desire comes anger.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-62', 'en', 'Trouble starts small, with what we keep thinking about. Watch your thoughts early and you stop the chain before it reaches anger.', 'This verse and the next describe a chain reaction in the mind. It begins innocently: we keep thinking about something we like. Thinking becomes attachment (saṅga). Attachment becomes desire (kāma). When desire is blocked, it turns into anger (krodha). The next verse continues: anger brings confusion, confusion destroys memory and judgement, and then a person falls. The teaching is hopeful, because the earliest link, where our attention goes, is the easiest place to step in.', '[{"word":"dhyāyataḥ","meaning":"dwelling on, brooding over"},{"word":"saṅga","meaning":"attachment"},{"word":"kāma","meaning":"desire, craving"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-62-story', 'Ravana''s desire', 'In the Ramayana, Ravana hears of Sita''s beauty and cannot stop thinking of her. That thought grows into obsession, then into the abduction of Sita, and finally into the war that destroys his kingdom.', 'A brooding ten-headed king on a golden throne in Lanka, one hand clenched, dark clouds gathering behind.');
insert into verse_stories (verse_id, story_id) values ('gita-2-62', 'gita-2-62-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-62', 'en', 'Catch the first link', 'When you notice yourself replaying something you want, gently switch your attention to something else before it turns into craving.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-62', 'What does dwelling on sense objects lead to first?', array['Anger', 'Attachment', 'Peace', 'Wisdom']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-62', 'According to this verse, anger comes from...', array['Desire', 'Hunger', 'Sleep', 'Silence']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-3-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 19, 'Chapter 3, Verse 19', 'तस्मादसक्तः सततं कार्यं कर्म समाचर।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-19', 'en', 'Therefore, always do the work that must be done, without attachment. By working without attachment, a person reaches the highest.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-3-19', 'en', 'You do not need to run away from the world to grow spiritually. Doing your duties with a free heart is itself the path.', 'In chapter three Arjuna asks why he should act at all if knowledge is higher than action. Krishna answers that action is unavoidable, so the question is how to act. The key word is asakta, unattached. Do the work that is yours to do, kārya, steadily and without clinging to rewards. Such work purifies the mind and leads to the highest good. This makes spiritual life possible for ordinary people with jobs and families, not only for monks.', '[{"word":"asakta","meaning":"unattached"},{"word":"kārya","meaning":"what ought to be done, duty"},{"word":"param","meaning":"the highest"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-3-19-story', 'King Janaka', 'In the very next verse, Krishna names King Janaka as an example. Janaka ruled a kingdom, managed courts and armies, and yet was known as a sage, because he did his work without clinging to it.', 'A king on a simple throne listening to petitioners, with a meditative stillness about him.');
insert into verse_stories (verse_id, story_id) values ('gita-3-19', 'gita-3-19-story');
insert into teachings (verse_id, language, title, practice) values ('gita-3-19', 'en', 'Do the next right thing', 'Pick one duty you have been avoiding and do it today, simply because it needs doing.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-19', 'How should necessary work be done?', array['With attachment', 'Without attachment', 'Only by priests', 'Only when rewarded']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-19', 'Which king is given as an example of this teaching?', array['Ravana', 'Janaka', 'Kamsa', 'Duryodhana']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-3-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 21, 'Chapter 3, Verse 21', 'यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-21', 'en', 'Whatever a great person does, others follow. Whatever standard they set, the world follows it.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-3-21', 'en', 'People learn more from what we do than from what we say. Anyone with influence, at home or at work, is setting an example.', 'Krishna explains why even a wise person who needs nothing should keep working: others are watching. The word śreṣṭha means the best or most respected person in a group. Whatever standard (pramāṇa) they set becomes the norm. Parents, teachers, managers and public figures all carry this responsibility. In the following verses Krishna says that he himself keeps acting, though he has nothing to gain, so that the world is not led astray.', '[{"word":"śreṣṭha","meaning":"the best, a leader"},{"word":"pramāṇa","meaning":"standard, example"},{"word":"anuvartate","meaning":"follows after"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-3-21-story', 'Rama, the model king', 'In the Ramayana, Rama is remembered as maryada purushottama, the ideal person who keeps to right conduct. He kept his promises even when it cost him, and the people of Ayodhya modelled their lives on his example.', 'Rama walking among ordinary townspeople in Ayodhya, children imitating his gentle posture.');
insert into verse_stories (verse_id, story_id) values ('gita-3-21', 'gita-3-21-story');
insert into teachings (verse_id, language, title, practice) values ('gita-3-21', 'en', 'Be the example', 'Think of one person who looks up to you. Do one thing today that you would be happy for them to copy.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-21', 'What do ordinary people do, according to this verse?', array['Ignore leaders', 'Follow the example of great people', 'Make their own rules', 'Avoid work']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-21', 'What is the main lesson?', array['Leaders can do as they like', 'Our actions set standards for others', 'Only words matter', 'Follow no one']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-3-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 35, 'Chapter 3, Verse 35', 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-35', 'en', 'It is better to follow your own duty imperfectly than to follow another''s duty perfectly. It is better even to die in your own duty; another''s duty is full of danger.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-3-35', 'en', 'Live your own life, not a copy of someone else''s. Your own path, done imperfectly, is worth more than borrowed success.', 'Svadharma means your own dharma, the duty and path that fits your nature, abilities and situation. Paradharma is someone else''s. Krishna says even an imperfect effort on your own path is better than a perfect copy of another''s. Arjuna, a protector by role, wanted to escape into the life of a renunciate; Krishna warns that this would be living against his grain. Today it reminds us that comparison is costly and that authenticity is a form of courage.', '[{"word":"svadharma","meaning":"one''s own duty or path"},{"word":"paradharma","meaning":"another''s duty"},{"word":"viguṇa","meaning":"imperfect, lacking merit"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-3-35-story', 'The warrior who wanted to be a monk', 'Arjuna, a warrior by nature and duty, told Krishna he would rather live as a beggar than fight. Krishna reminds him that running from his own role into someone else''s would not bring him peace.', 'Arjuna imagining himself as a wandering monk in a thought bubble, while Krishna gently points to the bow beside him.');
insert into verse_stories (verse_id, story_id) values ('gita-3-35', 'gita-3-35-story');
insert into teachings (verse_id, language, title, practice) values ('gita-3-35', 'en', 'Stop comparing', 'When you catch yourself envying someone''s path today, ask: what is my own next step? Then take it.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-35', 'Which is better, according to this verse?', array['Another''s duty done perfectly', 'Your own duty, even done imperfectly', 'No duty at all', 'Whatever pays most']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-35', 'What is ''svadharma''?', array['Your own duty or path', 'A type of prayer', 'A festival', 'A weapon']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-4-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 7, 'Chapter 4, Verse 7', 'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-7', 'en', 'Whenever righteousness declines and unrighteousness rises, O Arjuna, then I manifest myself.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-4-7', 'en', 'However dark things get, goodness is never abandoned. The divine steps in when the world needs it most.', 'In chapter four Krishna reveals that he has taken birth many times. This verse gives the reason. Dharma is the order that holds life together: truth, fairness, duty and care. When it weakens (glāni) and adharma rises, the divine takes form to restore balance. This verse, with the next, is the basis of the teaching of avatāras, divine descents. It also carries a promise of hope: no age is so dark that goodness is abandoned.', '[{"word":"dharma","meaning":"righteousness, the order that sustains life"},{"word":"glāni","meaning":"decline, weakening"},{"word":"sṛjāmi","meaning":"I manifest, I send forth"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-4-7-story', 'The promise of the avatars', 'Indian tradition tells of Vishnu taking many forms, the avatars, to restore balance: Rama in the Treta age and Krishna in the Dvapara age among them. Here Krishna himself explains why he comes.', 'A luminous blue figure appearing above a darkened world, light spreading outward like dawn.');
insert into verse_stories (verse_id, story_id) values ('gita-4-7', 'gita-4-7-story');
insert into teachings (verse_id, language, title, practice) values ('gita-4-7', 'en', 'Be part of the answer', 'Notice one small wrong around you today, an unkind word or some litter, and quietly set it right.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-7', 'When does Krishna say he manifests?', array['Every new year', 'When righteousness declines', 'Only in temples', 'Never']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-7', 'What is ''dharma'' closest to in this verse?', array['Wealth', 'Righteousness', 'Power', 'Luck']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-4-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 8, 'Chapter 4, Verse 8', 'परित्राणाय साधूनां विनाशाय च दुष्कृताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-8', 'en', 'To protect the good, to destroy evil, and to firmly establish righteousness, I come into being age after age.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-4-8', 'en', 'Protecting the good and standing against harm is a sacred act. In every age, goodness is renewed.', 'This verse completes the previous one by naming the purpose of each divine descent: to protect the good (sādhu), to remove those who do harm, and to firmly re-establish dharma. The phrase yuge yuge, age after age, tells us this is not a single event but a recurring pattern. Many readers also take it inwardly: whenever our own inner goodness is threatened, a higher strength can rise within us to protect it.', '[{"word":"paritrāṇa","meaning":"protection, rescue"},{"word":"sādhu","meaning":"good, virtuous person"},{"word":"yuge yuge","meaning":"in every age"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-4-8-story', 'Born in a prison', 'Krishna was born at midnight in the prison of the tyrant Kamsa, who feared him. The guards fell asleep, the doors opened, and his father Vasudeva carried the baby across the flooded Yamuna to safety in Gokul.', 'A father wading through a stormy river at night, holding a baby in a basket above his head, a great serpent sheltering them.');
insert into verse_stories (verse_id, story_id) values ('gita-4-8', 'gita-4-8-story');
insert into teachings (verse_id, language, title, practice) values ('gita-4-8', 'en', 'Protect someone', 'Stand up today for someone who is being treated unfairly, even in a small way.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-8', 'Why does Krishna come ''age after age''?', array['To collect offerings', 'To protect the good and establish righteousness', 'To rule the earth', 'To test people']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-8', 'Where was Krishna born, according to tradition?', array['In a palace', 'In Kamsa''s prison', 'In a forest', 'In Lanka']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-5-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 18, 'Chapter 5, Verse 18', 'विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-18', 'en', 'The wise see with an equal eye a learned and humble scholar, a cow, an elephant, a dog and an outcaste.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-5-18', 'en', 'True wisdom sees the same divine spark in every being, regardless of status, species or background.', 'This verse lists beings that society ranked very differently: a learned and humble scholar, a cow, an elephant, a dog, and an outcaste. The wise, paṇḍitāḥ, look at all of them with sama-darśana, an equal eye. This does not deny that people are different. It says the same divine reality is present in each, so dignity and respect are owed to all. It is one of the Gita''s strongest statements against prejudice.', '[{"word":"sama-darśin","meaning":"one who sees equally"},{"word":"paṇḍita","meaning":"a wise person"},{"word":"vinaya","meaning":"humility"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-5-18-story', 'Shankara meets an outcaste', 'A traditional story tells that the philosopher Adi Shankara, walking in Kashi, asked an outcaste to move out of his way. The man asked whether he meant his body or his Self, since the Self is the same in all. Shankara bowed to him as his teacher.', 'A young monk bowing before a humble man with four dogs on the ghats of a riverside city at dawn.');
insert into verse_stories (verse_id, story_id) values ('gita-5-18', 'gita-5-18-story');
insert into teachings (verse_id, language, title, practice) values ('gita-5-18', 'en', 'Equal eyes', 'Greet everyone you meet today, the cleaner, the shopkeeper, the stranger, with the same warmth you would give an honoured guest.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-5-18', 'How do the wise see all beings?', array['By rank', 'With an equal eye', 'By wealth', 'By caste']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-5-18', 'In the story, what did Shankara do after the conversation?', array['Walked away angry', 'Bowed to the man as his teacher', 'Called the guards', 'Left the city']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-6-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 5, 'Chapter 6, Verse 5', 'उद्धरेदात्मनात्मानं नात्मानमवसादयेत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-5', 'en', 'Lift yourself up by your own self; do not let yourself sink down. For the self alone is your friend, and the self alone is your enemy.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-6-5', 'en', 'You can be your own best friend or your own worst enemy. Growth starts when you decide to lift yourself.', 'Krishna uses one word, ātman, in two senses here: the higher self and the everyday self. Lift the everyday self up with the higher self; do not drag yourself down. You can be your own best friend (bandhu) or your own worst enemy (ripu). The following verse explains that the self is a friend to one who has mastered it, and an enemy to one who has not. It is an early, powerful call to self-responsibility: no one else can do your inner work for you.', '[{"word":"uddharet","meaning":"one should lift up"},{"word":"bandhu","meaning":"friend, kin"},{"word":"ripu","meaning":"enemy"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-6-5-story', 'From robber to poet', 'Tradition tells that Valmiki was once a highway robber named Ratnakara. When the sage Narada asked whether his family would share the burden of his sins, and they said no, he turned inward, meditated for years, and became the poet who wrote the Ramayana.', 'A man in deep meditation as an anthill rises around him, the forest glowing softly.');
insert into verse_stories (verse_id, story_id) values ('gita-6-5', 'gita-6-5-story');
insert into teachings (verse_id, language, title, practice) values ('gita-6-5', 'en', 'Talk to yourself like a friend', 'When you notice harsh self-talk today, rephrase it the way a good friend would say it to you.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-5', 'Who can lift you up, according to this verse?', array['Only others', 'Your own self', 'Only luck', 'No one']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-5', 'The self can be your...', array['Friend only', 'Enemy only', 'Friend or enemy', 'Neither']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-6-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 17, 'Chapter 6, Verse 17', 'युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-17', 'en', 'For one who is moderate in eating and recreation, balanced in work, and regular in sleep and waking, yoga becomes the destroyer of sorrow.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-6-17', 'en', 'Spiritual life is built on simple, balanced daily habits. Not too much, not too little.', 'In chapter six Krishna teaches meditation, and he is practical. Yoga does not succeed for someone who overeats or starves, or who sleeps too much or too little. The word yukta means fitting or balanced. Balanced food (āhāra), balanced recreation (vihāra), balanced effort in work, and regular sleep and waking create the conditions where yoga becomes duḥkha-hā, the destroyer of sorrow. The spiritual path is built on simple daily habits.', '[{"word":"yukta","meaning":"balanced, moderate"},{"word":"āhāra","meaning":"food, eating"},{"word":"duḥkha-hā","meaning":"destroyer of sorrow"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-6-17-story', 'Not too much, not too little', 'Just before this verse, Krishna warns that yoga is not for one who eats too much or starves, or who sleeps too much or too little. The path he teaches is one of balance, not extremes.', 'A simple meal, a lamp and a bedroll arranged neatly in a sunlit hut, suggesting a balanced day.');
insert into verse_stories (verse_id, story_id) values ('gita-6-17', 'gita-6-17-story');
insert into teachings (verse_id, language, title, practice) values ('gita-6-17', 'en', 'One balanced habit', 'Pick one area, food, screens or sleep, and bring it back to moderation today.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-17', 'What does this verse recommend?', array['Extreme fasting', 'Moderation in food, work and sleep', 'Sleeping as much as possible', 'Constant work']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-17', 'For the balanced person, yoga becomes...', array['A burden', 'The destroyer of sorrow', 'Impossible', 'A competition']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-6-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 26, 'Chapter 6, Verse 26', 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-26', 'en', 'Wherever the restless, unsteady mind wanders, from there one should draw it back and bring it under the control of the Self.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-6-26', 'en', 'The mind will wander; that is its nature. The practice is simply to bring it back, again and again, without frustration.', 'Krishna knows the mind well. He calls it cañcala, restless, and asthira, unsteady. It will wander. The instruction is not to be harsh with it but to bring it back, every time, from wherever it has gone. A few verses later Arjuna admits the mind is as hard to hold as the wind, and Krishna agrees, adding that practice (abhyāsa) and letting go (vairāgya) make it possible. Every return is a small success.', '[{"word":"cañcala","meaning":"restless, flickering"},{"word":"niyamya","meaning":"having restrained, drawing back"},{"word":"vaśa","meaning":"control"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-6-26-story', 'The eye of the bird', 'In the Mahabharata, the teacher Drona placed a wooden bird in a tree and asked his students what they saw. Some saw the tree, the branches, their brothers. Arjuna said he saw only the bird''s eye, and only he was allowed to shoot.', 'A young archer drawing his bow, everything blurred except a small wooden bird''s eye in sharp focus.');
insert into verse_stories (verse_id, story_id) values ('gita-6-26', 'gita-6-26-story');
insert into teachings (verse_id, language, title, practice) values ('gita-6-26', 'en', 'Bring it back', 'Do one task today with full attention. Each time your mind wanders, gently bring it back without scolding yourself.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-26', 'What should you do when the mind wanders?', array['Give up', 'Draw it back gently', 'Follow it', 'Get angry at it']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-26', 'In the story, what did Arjuna see?', array['The whole tree', 'His brothers', 'Only the bird''s eye', 'The sky']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-9-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 22, 'Chapter 9, Verse 22', 'अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-22', 'en', 'To those who worship me with single-minded devotion, always united with me, I bring what they lack and preserve what they have.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-9-22', 'en', 'Wholehearted trust brings a deep sense of being looked after. You are not carrying your life alone.', 'Chapter nine is called the royal secret. Here Krishna speaks to those who are ananya, whose devotion is not divided, who think of him and stay connected. To them he promises yoga-kṣema. Yoga here means gaining what you lack and kṣema means keeping what you have. In other words, he carries their welfare. This verse is beloved in India and is often seen on homes and offices as a reminder that sincere trust is answered.', '[{"word":"ananya","meaning":"undivided, with no other"},{"word":"yoga-kṣema","meaning":"gaining what is needed and keeping what is gained"},{"word":"vahāmi","meaning":"I carry"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-9-22-story', 'Draupadi''s call', 'When Draupadi was dragged into the royal court and humiliated, no elder came to her help. She raised her hands and called on Krishna with complete trust, and the cloth kept growing endlessly so she could not be shamed.', 'A woman with hands raised in prayer as an endless stream of bright cloth flows around her in a royal hall.');
insert into verse_stories (verse_id, story_id) values ('gita-9-22', 'gita-9-22-story');
insert into teachings (verse_id, language, title, practice) values ('gita-9-22', 'en', 'Hand over one worry', 'Write down one worry you cannot control. Offer it up in your own words, then turn your attention to what you can do.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-22', 'What does Krishna promise single-minded devotees?', array['Fame', 'To bring what they lack and keep what they have', 'A long life', 'Victory in war']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-22', 'In the story, who called on Krishna for help?', array['Sita', 'Draupadi', 'Kunti', 'Radha']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-9-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 26, 'Chapter 9, Verse 26', 'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-26', 'en', 'Whoever offers me with love a leaf, a flower, a fruit or a little water, that offering of love from a pure heart I accept.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-9-26', 'en', 'It is the love behind a gift that matters, not its size or cost.', 'After describing his vast cosmic forms, Krishna becomes tender. He asks for nothing grand: a leaf (patra), a flower (puṣpa), a fruit (phala) or water (toya). What matters is bhakti, love, and a sincere heart. This verse is the foundation of the simple offerings made in Indian homes every day. It also teaches a wider truth: the value of any gift lies in the love and attention behind it, not in its price.', '[{"word":"bhakti","meaning":"loving devotion"},{"word":"patraṁ puṣpaṁ phalaṁ toyam","meaning":"a leaf, a flower, a fruit, water"},{"word":"prayatātman","meaning":"one with a pure heart"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-9-26-story', 'Sudama''s rice', 'Sudama, Krishna''s poor childhood friend, visited him in Dwaraka with only a handful of flattened rice wrapped in cloth. Embarrassed, he tried to hide it, but Krishna took it and ate it with joy, treasuring it above any royal gift.', 'A king in fine robes joyfully eating rice from a worn cloth bundle, a thin poor man watching with tears.');
insert into verse_stories (verse_id, story_id) values ('gita-9-26', 'gita-9-26-story');
insert into teachings (verse_id, language, title, practice) values ('gita-9-26', 'en', 'Give small, give with love', 'Offer something small today, a kind note, a cup of tea, a flower, with full attention and love.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-26', 'What matters most in an offering, according to this verse?', array['Its price', 'The love behind it', 'Its size', 'Who sees it']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-26', 'What did Sudama bring to Krishna?', array['Gold coins', 'A handful of flattened rice', 'A horse', 'Silk clothes']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-12-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 13, 'Chapter 12, Verse 13', 'अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-13', 'en', 'One who hates no being, who is friendly and compassionate, free from possessiveness and ego, even-minded in pain and pleasure, and forgiving, is dear to me.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-12-13', 'en', 'This is a portrait of a good heart: no hatred, plenty of kindness, little ego, and an easy willingness to forgive.', 'Chapter twelve is about bhakti, and verses 13 to 20 describe the qualities of a person dear to God. This first verse lists several: free of hatred toward any being, friendly (maitra), compassionate (karuṇa), without possessiveness or ego, steady in pain and pleasure, and forgiving (kṣamī). Notice that these are not rituals but qualities of character. Many people read these verses slowly as a checklist for who they want to become.', '[{"word":"adveṣṭā","meaning":"one without hatred"},{"word":"karuṇa","meaning":"compassionate"},{"word":"kṣamī","meaning":"forgiving"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-12-13-story', 'Yudhishthira and the dog', 'At the end of the Mahabharata, Yudhishthira climbs toward heaven followed by a faithful dog. When told he may enter but the dog may not, he refuses to abandon it. The dog reveals itself as Dharma, his father, testing his compassion.', 'A king standing at a radiant gate, refusing to step through, a small dog at his feet on a snowy mountain.');
insert into verse_stories (verse_id, story_id) values ('gita-12-13', 'gita-12-13-story');
insert into teachings (verse_id, language, title, practice) values ('gita-12-13', 'en', 'Forgive one thing', 'Choose one small hurt you are holding on to and decide to let it go today.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-12-13', 'Which quality is listed in this verse?', array['Pride', 'Compassion', 'Ambition', 'Fear']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-12-13', 'In the story, why did Yudhishthira refuse to enter heaven?', array['He was afraid', 'He would not abandon the dog', 'He was tired', 'He wanted more gold']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-18-66', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 66, 'Chapter 18, Verse 66', 'सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-66', 'en', 'Setting aside all other duties, take refuge in me alone. I will free you from all wrongs. Do not grieve.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-18-66', 'en', 'After all the teachings, the final word is trust. Let go of anxiety and rest in the divine.', 'This is often called the carama śloka, the final and crowning verse of the Gita''s teaching. After eighteen chapters on action, knowledge, meditation and devotion, Krishna says: set aside every other support and take refuge (śaraṇa) in me alone. I will free you from all wrongs. Do not grieve. Teachers explain it in different ways, but all agree it is about complete trust. The Gita began with Arjuna''s grief, and it ends with mā śucaḥ, do not grieve.', '[{"word":"śaraṇa","meaning":"refuge, shelter"},{"word":"mokṣayiṣyāmi","meaning":"I will set you free"},{"word":"mā śucaḥ","meaning":"do not grieve"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-18-66-story', 'Arjuna''s doubt is gone', 'After hearing this final teaching, Arjuna tells Krishna that his confusion is destroyed and his memory restored. He picks up his bow, ready to act. The conversation that began with grief ends with clarity.', 'Arjuna standing tall in the chariot with his bow raised, Krishna holding the reins, light breaking over the battlefield.');
insert into verse_stories (verse_id, story_id) values ('gita-18-66', 'gita-18-66-story');
insert into teachings (verse_id, language, title, practice) values ('gita-18-66', 'en', 'Rest in trust', 'Before sleeping tonight, let go of the day''s worries one by one and say: I have done my part.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-18-66', 'What does Krishna tell Arjuna not to do?', array['Fight', 'Grieve', 'Pray', 'Think']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-18-66', 'Where does this verse appear in the Gita?', array['At the very beginning', 'Near the end, in the last chapter', 'In the middle', 'It is not in the Gita']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-3-62-10', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 3), 10, 'Mandala 3, Hymn 62, Verse 10 (Gayatri Mantra)', 'तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-3-62-10', 'en', 'We meditate on the glorious radiance of the divine Savitr, the source of all light. May it inspire and awaken our minds.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-3-62-10', 'en', 'This is a prayer not for wealth but for a clear, awakened mind. It asks the light that lights the sun to light our thinking too.', 'The Gayatri is named after its metre, gāyatrī, three lines of eight syllables. It is addressed to Savitṛ, the divine power behind the sun that stirs all life into action. The prayer does not ask for health or wealth. It asks that this radiant light, bharga, would inspire our minds, dhī. For thousands of years it has been chanted at dawn and dusk. The opening words om bhūr bhuvaḥ svaḥ, often added before it, come from a separate tradition.', '[{"word":"savitṛ","meaning":"the divine sun, the inspirer"},{"word":"bharga","meaning":"radiance, light"},{"word":"dhī","meaning":"mind, understanding"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-3-62-10-story', 'The seer Vishvamitra', 'This hymn is credited to the seer Vishvamitra, a king who gave up his throne to seek wisdom. Through long discipline he became a great rishi, and the Gayatri he received became one of the most chanted verses in India.', 'A sage standing waist-deep in a river at sunrise, palms joined, facing a golden sun.');
insert into verse_stories (verse_id, story_id) values ('rv-3-62-10', 'rv-3-62-10-story');
insert into teachings (verse_id, language, title, practice) values ('rv-3-62-10', 'en', 'Ask for clarity', 'At sunrise or when you start your day, take a moment to ask for a clear mind rather than a particular result.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-3-62-10', 'What does the Gayatri Mantra ask for?', array['Wealth', 'An awakened, inspired mind', 'Victory', 'Rain']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-3-62-10', 'Which Veda contains this verse?', array['Sama Veda', 'Rig Veda', 'Atharva Veda', 'None']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-1-164-46', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 1), 46, 'Mandala 1, Hymn 164, Verse 46', 'इन्द्रं मित्रं वरुणमग्निमाहुरथो दिव्यः स सुपर्णो गरुत्मान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-1-164-46', 'en', 'They call it Indra, Mitra, Varuna, Agni, and the heavenly bird Garutman. Truth is one; the wise call it by many names: Agni, Yama, Matarishvan.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-1-164-46', 'en', 'Different people use different names and paths for the same ultimate truth. This verse is a root of respect for many views.', 'This line is one of the most famous statements of the Rig Veda. It lists many names of gods, including Indra, Mitra, Varuna, Agni, the heavenly bird and Yama, and then says ekaṁ sad viprā bahudhā vadanti: truth is one, the wise speak of it in many ways. It is the root of a long Indian tradition of respecting many paths. People do not have to use the same words to point at the same reality.', '[{"word":"ekam","meaning":"one"},{"word":"sat","meaning":"truth, being, reality"},{"word":"bahudhā","meaning":"in many ways"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-1-164-46-story', 'The riddle hymn of Dirghatamas', 'This verse comes from a long hymn of riddles credited to the seer Dirghatamas, who tradition says was born blind. Though he could not see the world, he saw a deep truth: behind the many gods, there is one reality.', 'An elderly seer with closed eyes, surrounded by faint symbols of fire, wind, sky and water merging into one light.');
insert into verse_stories (verse_id, story_id) values ('rv-1-164-46', 'rv-1-164-46-story');
insert into teachings (verse_id, language, title, practice) values ('rv-1-164-46', 'en', 'Listen for the one', 'When you hear someone describe a belief different from yours today, look for the shared truth beneath the different words.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-164-46', '''Ekam sat'' means...', array['Many truths', 'Truth is one', 'No truth', 'Truth is hidden']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-164-46', 'How do the wise speak of the one truth?', array['By one name only', 'By many names', 'They never speak of it', 'Only in secret']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-10-129-1', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 10), 1, 'Mandala 10, Hymn 129, Verse 1 (Nasadiya Sukta)', 'नासदासीन्नो सदासीत्तदानीं नासीद्रजो नो व्योमा परो यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-10-129-1', 'en', 'Then there was neither non-existence nor existence. There was no air, nor sky beyond it. What covered it, and where? Who protected it? Was there water, deep and unfathomable?', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-10-129-1', 'en', 'One of the oldest scriptures in the world begins its story of creation with honest questions. Wonder, not certainty, is the starting point.', 'The Nasadiya Sukta, the Hymn of Creation, is one of the most philosophical poems in the Rig Veda. It imagines the state before anything existed, when there was neither being (sat) nor non-being (asat), no air and no sky. It does not give a neat answer. It asks questions, and later verses suggest that even the highest overseer may not know how it all began. Scientists and poets around the world admire it for its honest wonder.', '[{"word":"asat / sat","meaning":"non-being / being"},{"word":"vyoman","meaning":"sky, space"},{"word":"gabhīra","meaning":"deep, profound"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-10-129-1-story', 'The hymn of creation', 'The Nasadiya Sukta asks how everything began. It ends by saying that perhaps even the one who watches over creation from the highest heaven knows, or perhaps does not know. It is an ancient invitation to keep asking.', 'A vast dark cosmos with the first faint swirl of light, a tiny seated figure gazing up in wonder.');
insert into verse_stories (verse_id, story_id) values ('rv-10-129-1', 'rv-10-129-1-story');
insert into teachings (verse_id, language, title, practice) values ('rv-10-129-1', 'en', 'Stay curious', 'Ask one big question today that you do not know the answer to, and enjoy not knowing for a while.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-129-1', 'What is the Nasadiya Sukta about?', array['A war', 'The origin of the universe', 'A king''s wedding', 'Farming']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-129-1', 'How does this hymn approach creation?', array['With firm answers', 'With deep questions', 'With fear', 'With jokes']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-10-191-2', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 10), 2, 'Mandala 10, Hymn 191, Verse 2', 'सं गच्छध्वं सं वदध्वं सं वो मनांसि जानताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-10-191-2', 'en', 'Walk together, speak together, let your minds be in harmony, just as the gods of old sat together in agreement to share their portion.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-10-191-2', 'en', 'Communities thrive when people move, talk and think together. Harmony is something we practise, not just hope for.', 'This is part of the samjñāna sūkta, the hymn of togetherness, which closes the entire Rig Veda. Its verbs all begin with saṁ, meaning together: go together, speak together, let your minds know together. It points to the old gods, who shared their portions in harmony, as an example. The hymn is still recited at gatherings, schools and the start of meetings across India as a call for unity of purpose.', '[{"word":"saṁ gacchadhvam","meaning":"walk together"},{"word":"saṁ vadadhvam","meaning":"speak together"},{"word":"manāṁsi","meaning":"minds"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-10-191-2-story', 'The last hymn of the Rig Veda', 'This is part of the very last hymn of the Rig Veda. After more than a thousand hymns, the collection closes with a call for people to gather, speak and decide together in unity.', 'A circle of villagers of all ages seated around a fire under the stars, talking and listening.');
insert into verse_stories (verse_id, story_id) values ('rv-10-191-2', 'rv-10-191-2-story');
insert into teachings (verse_id, language, title, practice) values ('rv-10-191-2', 'en', 'Listen to agree', 'In one conversation today, listen fully before replying, and look for the point where you agree.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-191-2', 'What does this verse ask people to do?', array['Compete', 'Walk and speak together in harmony', 'Stay silent', 'Live alone']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-191-2', 'Where in the Rig Veda is this hymn found?', array['At the very beginning', 'At the very end', 'In the middle', 'It is not in the Rig Veda']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-1-89-1', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 1), 1, 'Mandala 1, Hymn 89, Verse 1', 'आ नो भद्राः क्रतवो यन्तु विश्वतोऽदब्धासो अपरीतास उद्भिदः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-1-89-1', 'en', 'Let noble thoughts come to us from every side, undeceived, unhindered and fresh. May the gods always be with us for our growth, ever watchful, protecting us day after day.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-1-89-1', 'en', 'Keep your mind open. Good ideas can come from anywhere and anyone, and welcoming them is how we grow.', 'The first line, ā no bhadrāḥ kratavo yantu viśvataḥ, is one of the most quoted lines of the Vedas. Bhadra means good or auspicious, and kratu means thought, will or purpose. The prayer asks that good thoughts come to us from every direction, undeceived and unblocked. The rest of the verse asks the gods to protect and help us grow day after day. It is a beautiful motto for an open, lifelong learner.', '[{"word":"bhadra","meaning":"good, auspicious"},{"word":"kratu","meaning":"thought, intention"},{"word":"viśvataḥ","meaning":"from all sides"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-1-89-1-story', 'An open door for wisdom', 'This verse is credited to the seer Gotama Rahugana. Its opening line is often quoted as a motto for learning: let good thoughts come to us from all directions, not just from people we already agree with.', 'A house with all its doors and windows open, beams of light entering from every direction.');
insert into verse_stories (verse_id, story_id) values ('rv-1-89-1', 'rv-1-89-1-story');
insert into teachings (verse_id, language, title, practice) values ('rv-1-89-1', 'en', 'Learn from someone unexpected', 'Learn one good idea today from a person or place you would not usually turn to.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-89-1', 'From where should noble thoughts come, according to this verse?', array['Only from teachers', 'From every side', 'Only from books', 'Only from family']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-89-1', 'What is the main lesson of this verse?', array['Keep an open mind', 'Avoid new ideas', 'Trust no one', 'Stay at home']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-7-59-12', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 7), 12, 'Mandala 7, Hymn 59, Verse 12 (Mahamrityunjaya Mantra)', 'त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-7-59-12', 'en', 'We worship the three-eyed one, fragrant, who nourishes all life. As a ripe cucumber is freed from its vine, may we be freed from death, and not from immortality.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-7-59-12', 'en', 'When the time comes, may we let go as naturally as ripe fruit falls from the vine, free and complete, not torn away.', 'Known as the Mahamrityunjaya, the great death-conquering mantra, this verse is addressed to Tryambaka, the three-eyed one, identified with Shiva. The image at its heart is gentle: a ripe cucumber (urvāruka) separates from its vine on its own, without force. The prayer asks to be released from death in the same natural way, and not from amṛta, immortality. It is chanted for healing, protection and peace, especially in times of illness.', '[{"word":"tryambaka","meaning":"the three-eyed one, Shiva"},{"word":"urvāruka","meaning":"cucumber or melon"},{"word":"amṛta","meaning":"immortality, nectar"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-7-59-12-story', 'Markandeya and Yama', 'In the Puranas, the boy Markandeya was destined to die at sixteen. When Yama came for him, he clung to a Shiva linga and chanted this mantra. Shiva appeared, stopped Yama, and blessed the boy with endless life.', 'A boy embracing a stone linga in a temple while a radiant figure of Shiva rises from it to face a startled Yama.');
insert into verse_stories (verse_id, story_id) values ('rv-7-59-12', 'rv-7-59-12-story');
insert into teachings (verse_id, language, title, practice) values ('rv-7-59-12', 'en', 'Ripen, then release', 'Think of something you are ready to let go of. Instead of tearing it away, let it fall away gently today.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-7-59-12', 'What image does this mantra use for liberation?', array['A bird leaving its nest', 'A ripe cucumber freed from its vine', 'A river reaching the sea', 'A lamp going out']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-7-59-12', 'In the story, who saved Markandeya?', array['Vishnu', 'Shiva', 'Indra', 'Brahma']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('av-12-1-12', 'atharva-veda', (select id from sections where scripture_id = 'atharva-veda' and level = 1 and number = 12), 12, 'Book 12, Hymn 1, Verse 12 (Bhumi Sukta, excerpt)', 'माता भूमिः पुत्रो अहं पृथिव्याः।', 'mātā bhūmiḥ putro ahaṁ pṛthivyāḥ', 12001012, true, 'public-domain-sanskrit', 'published');
insert into translations (verse_id, language, text, source_id, is_primary) values ('av-12-1-12', 'en', 'The Earth is my mother, and I am her child.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('av-12-1-12', 'en', 'We belong to the Earth; it does not belong to us. Caring for nature is caring for family.', 'The Bhumi Sukta in the Atharva Veda is a long hymn to the Earth, Prithvi. This short line from it, the Earth is my mother and I am her child, sums up its spirit. The hymn praises her hills, rivers and forests and the many peoples with different languages who live on her. It even asks that whatever we dig from her grow back quickly. Today many see it as one of the world''s earliest environmental poems.', '[{"word":"mātā","meaning":"mother"},{"word":"bhūmi / pṛthivī","meaning":"the Earth"},{"word":"putra","meaning":"child, son"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('av-12-1-12-story', 'The hymn to Mother Earth', 'The Bhumi Sukta is a long hymn of over sixty verses praising the Earth for her mountains, rivers, forests and the many peoples who live on her. It asks her forgiveness for the harm we do when we dig into her.', 'A child resting in the lap of a vast green landscape shaped like a mother, rivers flowing through her hair.');
insert into verse_stories (verse_id, story_id) values ('av-12-1-12', 'av-12-1-12-story');
insert into teachings (verse_id, language, title, practice) values ('av-12-1-12', 'en', 'Care for your mother', 'Do one thing for the Earth today: plant something, pick up litter, or use less plastic.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('av-12-1-12', 'How does this verse describe the Earth?', array['As a servant', 'As a mother', 'As an enemy', 'As a possession']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('av-12-1-12', 'Which Veda contains the Bhumi Sukta?', array['Rig Veda', 'Atharva Veda', 'Yajur Veda', 'Sama Veda']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('isha-1', 'isha-upanishad', null, 1, 'Verse 1', 'ईशा वास्यमिदं सर्वं यत्किञ्च जगत्यां जगत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('isha-1', 'en', 'All this, whatever moves in this moving world, is pervaded by the Lord. Enjoy it through renunciation. Do not covet anyone''s wealth.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('isha-1', 'en', 'Everything is sacred and nothing is truly ours. Enjoy life by holding it lightly, without greed.', 'The Isha Upanishad opens with a vision: everything that moves in this moving world is clothed in, or dwelt in by, the Lord (īśā). Since all is the divine''s, the verse advises tena tyaktena bhuñjīthāḥ, enjoy through letting go. It ends with mā gṛdhaḥ, do not covet. Mahatma Gandhi admired this verse deeply. It teaches that contentment comes not from owning more but from holding everything lightly and with reverence.', '[{"word":"īśā","meaning":"by the Lord"},{"word":"tyakta","meaning":"given up, let go"},{"word":"mā gṛdhaḥ","meaning":"do not covet"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('isha-1-story', 'The Upanishad inside a Veda', 'The Isha Upanishad is unusual: it is the final chapter of the Shukla Yajur Veda itself. In just eighteen verses, it brings the Vedic rituals to their inner meaning, beginning with this verse.', 'A person holding a flower in an open palm, light passing through everything around them.');
insert into verse_stories (verse_id, story_id) values ('isha-1', 'isha-1-story');
insert into teachings (verse_id, language, title, practice) values ('isha-1', 'en', 'Hold it lightly', 'Enjoy one thing you own today with gratitude, while remembering it is on loan to you.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('isha-1', 'According to this verse, the world is...', array['Meaningless', 'Pervaded by the divine', 'Owned by kings', 'An illusion to escape']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('isha-1', 'How should we enjoy the world?', array['Through greed', 'Through renunciation, holding it lightly', 'By taking what others have', 'We should not enjoy it']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('brihadaranyaka-1-3-28', 'brihadaranyaka-upanishad', (select id from sections where scripture_id = 'brihadaranyaka-upanishad' and level = 1 and number = 1), 28, 'Chapter 1, Section 3, Verse 28', 'असतो मा सद्गमय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('brihadaranyaka-1-3-28', 'en', 'Lead me from the unreal to the real. Lead me from darkness to light. Lead me from death to immortality.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('brihadaranyaka-1-3-28', 'en', 'Three short lines that sum up the whole spiritual journey: toward truth, toward understanding, toward what never dies.', 'These three lines are called the pavamāna mantras. Each line is a step: from asat (the unreal) to sat (the real), from tamas (darkness) to jyotis (light), and from mṛtyu (death) to amṛta (immortality). The Upanishad itself explains that all three mean the same thing: lead me from the passing to the lasting. Short enough for a child to learn, they hold the whole aim of the spiritual journey.', '[{"word":"asat / sat","meaning":"unreal / real"},{"word":"tamas / jyotis","meaning":"darkness / light"},{"word":"gamaya","meaning":"lead, cause to go"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('brihadaranyaka-1-3-28-story', 'A prayer for every journey', 'These lines come from one of the oldest Upanishads, where they are chanted as part of a Vedic ritual. Today they are sung in schools, homes and temples across India as a prayer for growth.', 'A path leading from a dark forest toward a glowing dawn horizon, a single lamp-bearer walking along it.');
insert into verse_stories (verse_id, story_id) values ('brihadaranyaka-1-3-28', 'brihadaranyaka-1-3-28-story');
insert into teachings (verse_id, language, title, practice) values ('brihadaranyaka-1-3-28', 'en', 'One step toward light', 'Replace one thing today that keeps you in ''darkness'', a rumour, a doom-scroll, a grudge, with something that brings light.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('brihadaranyaka-1-3-28', '''Tamaso ma jyotir gamaya'' means...', array['Lead me from darkness to light', 'Lead me to wealth', 'Lead me home', 'Lead me to victory']::text[], 0);
insert into quiz_questions (verse_id, question, options, answer_index) values ('brihadaranyaka-1-3-28', 'How many requests are in this prayer?', array['One', 'Two', 'Three', 'Ten']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('taittiriya-shanti', 'taittiriya-upanishad', null, 0, 'Invocation (Shanti Mantra)', 'ॐ सह नाववतु। सह नौ भुनक्तु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('taittiriya-shanti', 'en', 'May we both be protected together. May we both be nourished together. May we work together with energy. May our study be full of light, and may we never resent each other.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('taittiriya-shanti', 'en', 'Learning is a partnership. Teacher and student grow together when they share effort and respect.', 'A śānti mantra, or peace invocation, is recited before studying the Upanishads. This one is spoken by teacher and student together, which is why it uses the dual form nau, the two of us. It asks for protection, nourishment, shared energy and bright learning. The last line, mā vidviṣāvahai, asks that the two never resent each other. It closes with om śāntiḥ śāntiḥ śāntiḥ, peace three times.', '[{"word":"saha","meaning":"together"},{"word":"tejasvi","meaning":"radiant, full of light"},{"word":"mā vidviṣāvahai","meaning":"may we not resent each other"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('taittiriya-shanti-story', 'The gurukul prayer', 'In the ancient gurukuls, forest schools, teacher and students chanted this prayer together before lessons. It asks for success not for the student alone but for both of them, and for harmony between them.', 'A teacher and a few students seated under a tree in a forest school, hands joined, morning light filtering through leaves.');
insert into verse_stories (verse_id, story_id) values ('taittiriya-shanti', 'taittiriya-shanti-story');
insert into teachings (verse_id, language, title, practice) values ('taittiriya-shanti', 'en', 'Learn together', 'Teach someone one thing you know today, and ask them to teach you one thing back.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('taittiriya-shanti', 'Who chants this prayer together?', array['King and soldier', 'Teacher and student', 'Husband and wife', 'Priest and god']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('taittiriya-shanti', 'What does the last line ask for?', array['Wealth', 'That we never resent each other', 'Victory over enemies', 'Long life']::text[], 1);
